"category":"nha_sach","phone":"0357135145","place":"ChIJ8SnOB4wrdTERgsqb_BNgpfw","source":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20B%E1%BA%A1ch%20%C4%90%E1%BA%B1ng%20Nguy%E1%BB%85n%20Th%E1%BB%8B%20T%C3%BA%2066-71%20Nguy%E1%BB%85n%20Th%E1%BB%8B%20T%C3%BA%2C%20Khu%20ph%E1%BB%91%201%20TP%20Ho%20Chi%20Minh&query_place_id=ChIJ8SnOB4wrdTERgsqb_BNgpfw","maps":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20B%E1%BA%A1ch%20%C4%90%E1%BA%B1ng%20Nguy%E1%BB%85n%20Th%E1%BB%8B%20T%C3%BA%2066-71%20Nguy%E1%BB%85n%20Th%E1%BB%8B%20T%C3%BA%2C%20Khu%20ph%E1%BB%91%201%20TP%20Ho%20Chi%20Minh&query_place_id=ChIJ8SnOB4wrdTERgsqb_BNgpfw","key":"gmaps:ChIJ8SnOB4wrdTERgsqb_BNgpfw","address_new":"66-71 Nguyễn Thị Tú, Khu phố 1, phường Bình Tân, TP. Hồ Chí Minh","address_old":"66-71 Nguyễn Thị Tú, Khu phố 1, Quận Bình Tân cũ, TP.HCM cũ"}]'::jsonb) AS s(name text,street text,ward text,district text,category text,phone text,place text,source text,maps text,key text,address_new text,address_old text)
 WHERE s.category IN ('nha_sach','van_phong_pham')
 AND s.source LIKE 'https://%'
 AND (s.place IS NULL OR s.place ~ '^ChIJ[A-Za-z0-9_-]{20,}$')
 AND (s.maps IS NULL OR s.maps LIKE 'https://www.google.com/maps/%')
 AND s.address_new LIKE '% '||s.ward||', TP. Hồ Chí Minh'
 AND (s.phone IS NULL OR s.phone ~ '^[0-9]{8,11}$')
 AND EXISTS (SELECT 1 FROM public.sales_hcm_old_wards w WHERE w.province='TP Hồ Chí Minh' AND w.ward_new=s.ward AND w.legacy_district=s.district AND w.active)
 AND NOT EXISTS (SELECT 1 FROM public.field_prospects p WHERE p.research_source_key=s.key OR (s.place IS NOT NULL AND p.google_place_id=s.place) OR lower(btrim(p.address_line))=lower(btrim(s.address_new)) OR (p.province='TP Hồ Chí Minh' AND p.ward_new=s.ward AND lower(btrim(p.name))=lower(btrim(s.name))) OR (s.phone IS NOT NULL AND regexp_replace(coalesce(p.phone,''),'[^0-9]','','g')=s.phone))
 AND NOT EXISTS (SELECT 1 FROM public.customers c WHERE lower(btrim(c.address_line))=lower(btrim(s.address_new)) OR (c.province='TP Hồ Chí Minh' AND lower(btrim(c.name))=lower(btrim(s.name))) OR (s.phone IS NOT NULL AND regexp_replace(coalesce(c.phone,''),'[^0-9]','','g')=s.phone))
), inserted AS (
 INSERT INTO public.field_prospects(id,area_visit_id,owner_sub,name,address_line,province,district,ward_new,address_legacy,category,phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch,google_maps_url,google_place_id)
 SELECT gen_random_uuid(),NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_new,'TP Hồ Chí Minh',s.district,s.ward,s.address_old,s.category,s.phone,NULL,
 'Nguồn công khai tra cứu 22/11/2026; CHƯA GHÉ / CHƯA XÁC MINH bảng hiệu, GPS, tình trạng kinh doanh. Không coi kết quả Maps là kiểm chứng thực địa. Nguồn: '||s.source,
 'new','manual',s.key,s.source,'2026-11-22-hcm-old-phase1-181',s.maps,s.place
 FROM vetted s
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING district,ward_new,name,category,phone,google_place_id
)
SELECT district,ward_new,name,category,phone,google_place_id FROM inserted ORDER BY district,ward_new,name;
